  NOT((NEW.user_id IS NOT NULL AND NEW.institution_id IS NULL AND NEW.assignment_id IS NULL) OR
      (NEW.user_id IS NULL AND NEW.institution_id IS NOT NULL AND NEW.assignment_id IS NOT NULL)) THEN
