 IF NEW.revision_after<0 OR NEW.revision_before<0 OR CHAR_LENGTH(TRIM(NEW.reason))=0 OR NOT(REGEXP_LIKE(CONVERT(NEW.request_hash USING utf8mb4) COLLATE utf8mb4_bin, '^[0-9A-F]{64}\\z', 'c')) OR NOT EXISTS(SELECT 1 FROM institution_membership m JOIN institution_membership_role r ON r.membership_id=m.id JOIN institution i ON i.id=m.institution_id WHERE m.institution_id=NEW.institution_id AND m.id=NEW.actor_membership_id AND m.user_id=NEW.actor_user_id AND m.status='active' AND i.status='active' AND r.role='InstitutionAdmin') OR (NEW.version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM formative_plan_version v WHERE v.institution_id=NEW.institution_id AND v.id=NEW.version_id AND v.plan_id=NEW.plan_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid formative audit actor or resource'; END IF;
END

