 DECLARE parent char(36) CHARACTER SET ascii;
 SELECT id INTO parent FROM institution WHERE id=NEW.institution_id FOR UPDATE;
 IF NEW.id='00000000-0000-0000-0000-000000000000' OR NEW.category NOT IN ('Student','Teacher') OR NEW.state<>'Preview' OR NEW.revision<>1 OR NEW.payload IS NULL OR JSON_TYPE(NEW.payload)<>'OBJECT' OR NEW.result_json IS NOT NULL OR JSON_TYPE(NEW.warnings_json)<>'ARRAY' OR NEW.total_rows<1 OR NEW.total_rows>10000 OR NEW.valid_rows+NEW.invalid_rows<>NEW.total_rows OR NEW.expires_at_utc<=NEW.created_at_utc OR NOT(REGEXP_LIKE(CONVERT(NEW.file_sha256 USING utf8mb4) COLLATE utf8mb4_bin, '^[0-9A-F]{64}\\z', 'c')) OR NOT(REGEXP_LIKE(CONVERT(NEW.preview_digest USING utf8mb4) COLLATE utf8mb4_bin, '^[0-9A-F]{64}\\z', 'c')) OR
 NOT EXISTS(SELECT 1 FROM institution_membership m JOIN institution_membership_role r ON r.membership_id=m.id JOIN institution i ON i.id=m.institution_id WHERE m.institution_id=NEW.institution_id AND m.id=NEW.actor_membership_id AND m.user_id=NEW.actor_user_id AND m.status='active' AND i.status='active' AND r.role IN ('InstitutionAdmin','Staff')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Import preview ownership or state invalid'; END IF;
END

